import { z } from "zod";

import { badRequest } from "./http";

const finite = z.number().finite();
const unit = finite.min(0).max(1);
const isoDate = z.string().refine((s) => !Number.isNaN(Date.parse(s)), "must be an ISO 8601 date");
const base64 = z.string().regex(/^[A-Za-z0-9+/]+={0,2}$/, "must be base64");

/** What the worker POSTs when the incident rule fires. `id` is generated by the worker: it is the idempotency key. */
export const incidentIn = z
  .object({
    id: z.uuid(),
    trackerId: z.number().int().min(0),
    zoneId: z.string().max(100).nullable().optional(),
    zoneName: z.string().max(100).nullable().optional(),
    rule: z.string().min(1).max(50),
    startedAt: isoDate,
    triggeredAt: isoDate,
    durationS: finite.min(0),
    violatingFrames: z.number().int().min(1),
    windowFrames: z.number().int().min(1),
    confidence: unit,
    bbox: z.tuple([unit, unit, unit, unit]),
    snapshotJpegBase64: base64.nullable().optional(),
    rawJpegBase64: base64.nullable().optional(),
  })
  .refine((v) => v.violatingFrames <= v.windowFrames, { message: "violatingFrames must be <= windowFrames", path: ["violatingFrames"] })
  .refine((v) => Date.parse(v.startedAt) <= Date.parse(v.triggeredAt), { message: "startedAt must not be after triggeredAt", path: ["startedAt"] });

export type IncidentIn = z.infer<typeof incidentIn>;

export const reviewIn = z.object({ status: z.enum(["open", "confirmed", "false_alarm"]) });

export const zoneIn = z.object({
  name: z
    .string()
    .trim()
    .min(1, "Give the zone a name, for example Loading bay 2")
    .max(60, "Zone names can be up to 60 characters"),
  points: z.array(z.tuple([unit, unit])).min(3, "A zone needs at least 3 points").max(50, "A zone can have up to 50 points"),
});

export const loginIn = z.object({ password: z.string().min(1).max(200) });

export const listQuery = z.object({
  status: z.enum(["open", "confirmed", "false_alarm", "all"]).default("all"),
  zoneId: z.string().max(100).optional(),
  from: isoDate.optional(),
  to: isoDate.optional(),
  limit: z.coerce.number().int().min(1).max(200).default(50),
  cursor: z.string().max(200).optional(),
});

/** Parses or throws a 400 whose message names the first bad field. */
export function parse<T>(schema: z.ZodType<T>, value: unknown): T {
  const result = schema.safeParse(value);
  if (result.success) return result.data;
  const issue = result.error.issues[0];
  const where = issue.path.length ? `${issue.path.join(".")}: ` : "";
  throw badRequest(`${where}${issue.message}`, "validation_failed");
}
